import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import {
  generateDeflectionContracts,
  generateDeflectionReportModelContract,
  generateDeflectionSnapshotContract,
  renderDeflectionReportModelContract,
  renderDeflectionSnapshotContract,
} from './generate-deflection-snapshot-contract.mjs';

const SOURCE_FIXTURE = `/*
 * Generated by scripts/generate_deflection_frontend_contract_types.py.
 * Do not edit by hand; run the generator after backend contract changes.
 */

export const DEFLECTION_SNAPSHOT_SCHEMA_VERSION = "deflection.v1" as const;

export const DEFLECTION_SNAPSHOT_TOP_LEVEL_FIELDS = ["summary", "top_questions", "locked_questions", "top_blind_spots", "teaser"] as const;

export const DEFLECTION_RESULT_PAGE_SNAPSHOT_FIELDS = ["summary", "top_questions", "top_blind_spots"] as const;

export const DEFLECTION_SNAPSHOT_SUMMARY_FIELDS = ["generated", "drafted_answer_count", "no_proven_answer_count", "support_ticket_resolution_evidence_present", "support_ticket_resolution_evidence_count", "repeat_ticket_count", "non_repeat_ticket_count", "source_date_start", "source_date_end", "source_window_days"] as const;

export type DeflectionSnapshotSummary = {
  generated: number;
  drafted_answer_count: number;
  no_proven_answer_count: number;
  support_ticket_resolution_evidence_present: boolean;
  support_ticket_resolution_evidence_count: number;
  repeat_ticket_count: number;
  non_repeat_ticket_count: number;
};

export type DeflectionSnapshotTopQuestion = {
  rank: number;
  question: string;
  ticket_count: number;
  weighted_frequency: number;
  customer_wording: string;
};

export type DeflectionSnapshotLockedQuestion = {
  rank: number;
  ticket_count: number;
};

export type DeflectionSnapshotTopBlindSpot = {
  rank: number;
  question: string;
  ticket_count: number;
};

export type DeflectionSnapshotTeaserFullAnswer = {
  rank: number;
  question: string;
  answer: string;
  steps: string[];
  answer_evidence_status: string;
  resolution_evidence_scope: string;
  weighted_frequency: number;
  source_count: number;
};

export type DeflectionSnapshotTeaserPreview = {
  rank: number;
  question: string;
  answer_evidence_status: string;
  resolution_evidence_scope: string;
  weighted_frequency: number;
  step_count: number;
  source_count: number;
  body_withheld: boolean;
};

export type DeflectionSnapshotTeaser = {
  full_answer: DeflectionSnapshotTeaserFullAnswer | null;
  previews: DeflectionSnapshotTeaserPreview[];
};

export type DeflectionSnapshot = {
  summary: DeflectionSnapshotSummary;
  top_questions: DeflectionSnapshotTopQuestion[];
  locked_questions: DeflectionSnapshotLockedQuestion[];
  top_blind_spots: DeflectionSnapshotTopBlindSpot[];
  teaser: DeflectionSnapshotTeaser;
};
`;

const REPORT_MODEL_SOURCE_FIXTURE = `/*
 * Generated by scripts/generate_deflection_frontend_contract_types.py.
 * Do not edit by hand; run the generator after backend contract changes.
 */

export const DEFLECTION_REPORT_MODEL_SCHEMA_VERSION = "deflection.v1" as const;

export const DEFLECTION_REPORT_SECTION_IDS = ["support_tax", "priority_fix_queue", "complete_evidence"] as const;

export const DEFLECTION_REPORT_PRIORITY_FIX_QUEUE_FIELDS = ["items", "result_page_limit"] as const;

export const DEFLECTION_REPORT_COMPLETE_EVIDENCE_FIELDS = ["source_id_count", "evidence_row_count"] as const;

export type DeflectionReportSection = {
  id: string;
  title: string;
  priority: number;
  surfaces: string[];
  default_limit: number | null;
  required_data: string[];
  data: Record<string, unknown>;
};

export type DeflectionStructuredReport = {
  schema_version: "deflection.v1";
  title: string;
  summary: Record<string, unknown>;
  sections: DeflectionReportSection[];
};
`;

const rendered = renderDeflectionSnapshotContract(SOURCE_FIXTURE);
const compactRendered = renderDeflectionSnapshotContract(SOURCE_FIXTURE.replace(/\s+/g, ' '));
const reportModelRendered = renderDeflectionReportModelContract(REPORT_MODEL_SOURCE_FIXTURE);
assert.equal(
  compactRendered,
  rendered,
  'generator should normalize ATLAS source formatting before comparing output',
);
assert.ok(
  rendered.includes('Generated by web/scripts/generate-deflection-snapshot-contract.mjs'),
  'rendered contract should carry the portfolio generator header',
);
assert.ok(
  rendered.includes('export type DeflectionSnapshotQuestion = {'),
  'ATLAS top-question type should map to the stable portfolio import name',
);
assert.ok(
  rendered.includes('top_blind_spots: DeflectionSnapshotBlindSpot[];'),
  'required top_blind_spots should stay required after type-name mapping',
);
assert.ok(
  rendered.includes('support_ticket_resolution_evidence_present: boolean;'),
  'support-ticket evidence flag should stay in the generated summary type',
);
assert.ok(
  rendered.includes('export type DeflectionSnapshotSourceWindow = {'),
  'portfolio source-window helper alias should be appended',
);
assert.ok(
  reportModelRendered.includes('Generated by web/scripts/generate-deflection-snapshot-contract.mjs'),
  'report-model render should carry the portfolio generator header',
);
assert.ok(
  reportModelRendered.includes('export type DeflectionStructuredReport = {'),
  'report-model render should preserve the ATLAS paid report type',
);
assert.ok(
  reportModelRendered.includes('DEFLECTION_REPORT_PRIORITY_FIX_QUEUE_FIELDS'),
  'report-model render should preserve generated section field metadata',
);

assert.throws(
  () => renderDeflectionSnapshotContract(SOURCE_FIXTURE.replaceAll('non_repeat_ticket_count', '')),
  /missing required markers: non_repeat_ticket_count/,
  'source validation should fail closed when an ATLAS-required field disappears',
);
assert.throws(
  () => renderDeflectionReportModelContract(REPORT_MODEL_SOURCE_FIXTURE.replaceAll('DEFLECTION_REPORT_COMPLETE_EVIDENCE_FIELDS', '')),
  /missing required markers: DEFLECTION_REPORT_COMPLETE_EVIDENCE_FIELDS/,
  'report-model source validation should fail closed when an ATLAS-required marker disappears',
);

const testDir = await mkdtemp(join(tmpdir(), 'deflection-snapshot-contract-generator-'));
try {
  const sourcePath = join(testDir, 'deflectionSnapshot.ts');
  const reportModelSourcePath = join(testDir, 'deflectionReportModel.ts');
  const outputPath = join(testDir, 'deflection-snapshot-contract.ts');
  const reportModelOutputPath = join(testDir, 'deflection-report-model-contract.ts');
  await writeFile(sourcePath, SOURCE_FIXTURE, 'utf8');
  await writeFile(reportModelSourcePath, REPORT_MODEL_SOURCE_FIXTURE, 'utf8');
  await writeFile(outputPath, rendered, 'utf8');
  await writeFile(reportModelOutputPath, reportModelRendered, 'utf8');
  await generateDeflectionSnapshotContract({ check: true, outputPath, sourcePath });
  await generateDeflectionReportModelContract({
    check: true,
    reportModelOutputPath,
    reportModelSourcePath,
  });
  await generateDeflectionContracts({
    check: true,
    outputPath,
    reportModelOutputPath,
    reportModelSourcePath,
    sourcePath,
  });

  const driftedSource = SOURCE_FIXTURE.replace(
    'support_ticket_resolution_evidence_present: boolean;',
    'support_ticket_resolution_evidence_present: string;',
  );
  await writeFile(sourcePath, driftedSource, 'utf8');
  await assert.rejects(
    () => generateDeflectionSnapshotContract({ check: true, outputPath, sourcePath }),
    /is out of date/,
    'check mode should reject a valid ATLAS source whose rendered contract drifts from the committed output',
  );
  await writeFile(sourcePath, SOURCE_FIXTURE, 'utf8');

  await writeFile(outputPath, rendered.replace('DeflectionSnapshotQuestion', 'StaleQuestion'), 'utf8');
  await assert.rejects(
    () => generateDeflectionSnapshotContract({ check: true, outputPath, sourcePath }),
    /is out of date/,
    'check mode should reject a stale committed generated file',
  );
  await writeFile(outputPath, rendered, 'utf8');

  const driftedReportModelSource = REPORT_MODEL_SOURCE_FIXTURE.replace(
    'summary: Record<string, unknown>;',
    'summary: { generated: number };',
  );
  await writeFile(reportModelSourcePath, driftedReportModelSource, 'utf8');
  await assert.rejects(
    () => generateDeflectionReportModelContract({
      check: true,
      reportModelOutputPath,
      reportModelSourcePath,
    }),
    /is out of date/,
    'report-model check mode should reject a valid ATLAS source whose rendered contract drifts from the committed output',
  );
  await writeFile(reportModelSourcePath, REPORT_MODEL_SOURCE_FIXTURE, 'utf8');

  await writeFile(reportModelOutputPath, reportModelRendered.replace('DeflectionStructuredReport', 'StaleReport'), 'utf8');
  await assert.rejects(
    () => generateDeflectionReportModelContract({
      check: true,
      reportModelOutputPath,
      reportModelSourcePath,
    }),
    /is out of date/,
    'report-model check mode should reject a stale committed generated file',
  );

  const generatedPath = join(testDir, 'generated.ts');
  await generateDeflectionSnapshotContract({ outputPath: generatedPath, sourcePath });
  assert.equal(await readFile(generatedPath, 'utf8'), rendered);

  const generatedReportModelPath = join(testDir, 'generated-report-model.ts');
  await generateDeflectionReportModelContract({
    reportModelOutputPath: generatedReportModelPath,
    reportModelSourcePath,
  });
  assert.equal(await readFile(generatedReportModelPath, 'utf8'), reportModelRendered);
} finally {
  await rm(testDir, { recursive: true, force: true });
}

console.log('Deflection contract generator tests passed.');
